# frozen_string_literal: true

require "json"
require_relative "../presentation"
require_relative "save_files"
require_relative "declared"

module DotPopper
  module Privacy
    # doc/privacy.json: everything the game declares about a player's data,
    # for the public policy and the stores' labels, generated by
    # `bundle exec rake privacy`. A test fails if it is stale, so the words
    # in it are never older than the code.
    class Document
      PATH = File.expand_path("../../../doc/privacy.json", __dir__)
      FLEDGE = File.expand_path("../../../fledge.yml", __dir__)
      STALE = "doc/privacy.json is stale: run `bundle exec rake privacy` and commit it."

      def self.current_json = "#{JSON.pretty_generate(new.to_h)}\n"

      def to_h
        { game: "Dot Popper", game_version: version, on_device: on_device, network: network, purchases: PURCHASES, sdks: sdks, permissions: permissions,
          sensors: { accelerometer: SENSOR }, sharing: sharing, deletion: deletion, store_labels: store_labels,
          declared_but_not_enforced: NOT_ENFORCED.map { item(it) } }
      end

      # Every sentence meant for a player, for the test that keeps them plain.
      def player_words
        [*for_players, stays_on_the_device, PURCHASES, SENSOR, NO_OUTSIDE_SERVICES, sharing_how, *plain_sdks, *NOT_ENFORCED.filter_map(&:plain)]
      end

      private

      def version = File.read(FLEDGE)[/^version:\s*"([^"]+)"/, 1]

      def on_device
        { for_players: for_players, files: SAVE_FILES.map { file(it) }, stays_on_the_device: stays_on_the_device }
      end

      def for_players = SAVE_FILES.filter_map(&:label).uniq

      def file(kept)
        { name: kept.name, label: kept.label, not_for_players: kept.aside&.to_h, holds: kept.holds, made_by: kept.made_by, also_sent: kept.sent.values }
      end

      def stays_on_the_device
        sent = SAVE_FILES.flat_map { it.sent.values }.join(" and ")
        "These stay on your device until you uninstall the game or remove them. If you use friend groups, #{sent} also go to the game's server."
      end

      def network
        { server: Groups::Settings::SERVER_URL, every_request: "Sent to this server over HTTPS.",
          outside_services: NO_OUTSIDE_SERVICES, requests: Groups::REQUESTS.values.map { request(it) } }
      end

      def request(req)
        { kind: req.kind, method: req.verb.to_s.upcase, path: req.path, query: fields(req.query), body: fields(req.body),
          sends_token: req.token, when: req.happens, in_this_build: !Groups::UNBUILT_REQUESTS.include?(req.kind) }
      end

      def fields(hash) = hash.transform_values(&:what)

      def sdks
        { for_players: plain_sdks, ruby_gems: SHIPPED_GEMS.transform_values { item(it) }, android_dependencies: ANDROID_DEPENDENCIES.transform_values { item(it) },
          ios: item(IOS_FRAMEWORKS), outside_services: NO_OUTSIDE_SERVICES }
      end

      def plain_sdks = [*ANDROID_DEPENDENCIES.values, IOS_FRAMEWORKS].filter_map(&:plain)

      def item(entry) = { note: entry.note, plain: entry.plain, record_only: entry.record_only }

      def permissions
        { android_manifest: ANDROID_PERMISSIONS, android_added_by_libraries: ANDROID_MERGED, ios_usage_strings: IOS_USAGE_STRINGS,
          ios_privacy_manifest: { tracking: APPLE_TRACKING, tracking_domains: APPLE_TRACKING_DOMAINS, apis: APPLE_APIS } }
      end

      def sharing
        stats = GameStats.start.with(pops: 27, mistakes: 1, duration: 38.2)
        { how: sharing_how, example: Presentation::Style::WORDS.share_text(25, stats, score_record: 25, new_score_record: true) }
      end

      def sharing_how = "A result is shared only when you choose \"#{Presentation::Style::WORDS.share}\". The game doesn't send it anywhere itself."

      def deletion
        words = Presentation::GroupWords
        { screen: words.heading, control: words.delete, gesture: "press and hold for #{Presentation::GroupPanel::HOLD.to_i} seconds", prompt: words.hold_to_delete,
          sentence: "On the game's \"#{words.heading}\" screen, press and hold \"#{words.delete}\".", shown: "once this device has a token",
          request: Groups::REQUESTS.fetch(:deleted).then { "#{it.verb.to_s.upcase} #{it.path}" } }
      end

      def store_labels
        { apple: { tracking: APPLE_TRACKING, data_types: label_answers { |label, data| apple_answer(label, data) }, ip_addresses: "#{IP_ADDRESSES} Apple's list has no IP-address category, so it is not among the data types; if the maintainer or Apple's review reads \"Device ID\" as covering it, add that, linked and for App Functionality." },
          google: { collects_data: true, shares_with_other_parties: false, encrypted_in_transit: true, users_can_request_deletion: true,
                    data_types: label_answers { |label, data| google_answer(label, data) },
                    ip_addresses: "#{IP_ADDRESSES} The maintainer decides whether to list it under Device or other IDs." } }
      end

      def label_answers = STORE_LABELS.map { |label, data| yield(label, data) }

      def apple_answer(label, data)
        { type: data[:apple], name: data[:apple_name], linked: data[:apple_linked], why: data[:why_linked], purposes: [APPLE_PURPOSE], sent_by: kinds_with(label) }
      end

      def google_answer(label, data)
        { category: data[:google], optional: data[:google_optional], purpose: "App functionality", shared: false, sent_by: kinds_with(label) }
      end

      def kinds_with(label) = Groups::REQUESTS.values.select { it.labels.include?(label) }.map(&:kind)
    end
  end
end
